{
  "summary": "Rubicon grants ISA an exclusive, non-transferable license in the United States to market, sell, use, display, perform, sublicense, and distribute the Rubicon Offerings and Documentation, including upgrades.",
  "evidence": [
    {
      "passage_id": 4,
      "quote": "Rubicon hereby grants to ISA during the Term (as defined below) and subject to the exclusions described in 2.4 below an exclusive, non-transferable license in the United States to market, sell, use, display, perform, sublicense and distribute the Rubicon Offerings, the  Documentation and, subject to Section 2.2, any upgrades thereto, subject to the conditions set forth in this Agreement."
    },
    {
      "passage_id": 2,
      "quote": "Rubicon hereby grants to ISA during the Term and subject to the exclusions described in 2.4 below an exclusive, non-transferable  license in the United States to grant licenses to use, display, perform and distribute the Rubicon Offerings and the Documentation to other  resellers, including, but not limited to, distributors, Original Equipment Manufacturers, system integrators and Value-Added Resellers, for further  sale and distribution to End Users for their use as described above, subject to the conditions set forth in this Agreement."
    },
    {
      "passage_id": 2,
      "quote": "The license grants described in Sections 2.1 and 2.2 shall include all upgrades to the Rubicon Offerings and the Documentation."
    }
  ]
}
